async function getFlag(tenantId, flagName) {
  const key = `${tenantId}:${flagName}`;
  let val = await redis.get(key);
  if (val) return JSON.parse(val);
  const flag = await appConfig.getFlag(tenantId, flagName);
  await redis.setex(key, flag.ttl, JSON.stringify(flag));
  return flag;
}
```

